package org.diy.liferecorder;
import org.json.*;import java.util.*;import java.io.IOException;import org.diy.lifecore.LocalSecurity;
/** Encrypted named profiles with individually removable, source-linked samples. */
final class VoiceProfiles {
 static final String SELF="self";private static final Object LOCK=new Object();
 static JSONArray read(OfflinePacks packs)throws Exception{synchronized(LOCK){String stored=packs.prefs.getString("voice-profiles-v1","");if(!stored.isEmpty())return new JSONArray(LocalSecurity.open(stored));JSONArray all=new JSONArray();String old=packs.prefs.getString("my-voice","");if(!old.isEmpty()){JSONObject sample=new JSONObject().put("id",UUID.randomUUID().toString()).put("created",System.currentTimeMillis()).put("origin","legacy").put("profile",new JSONObject(LocalSecurity.open(old)));all.put(new JSONObject().put("id",SELF).put("name","本人").put("enabled",true).put("samples",new JSONArray().put(sample)));}return all;}}
 static JSONObject find(JSONArray all,String id)throws Exception{for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("id").equals(id))return all.getJSONObject(i);throw new IOException("声纹已删除，请刷新后重试");}
 static JSONObject combined(JSONObject person,String version)throws Exception{JSONObject result=null;JSONArray samples=person.getJSONArray("samples");int count=0;for(int i=0;i<samples.length();i++){JSONObject p=samples.getJSONObject(i).getJSONObject("profile");if(!p.optString("model_version").equals(version))continue;SpeakerMatcher.Profile profile=new SpeakerMatcher.Profile(p);result=SpeakerMatcher.profile(profile.templates,result==null?null:new SpeakerMatcher.Profile(result),result!=null,version);count+=p.optInt("samples",1);}if(result!=null)result.put("samples",Math.min(12,count));return result;}
 private static void write(OfflinePacks packs,JSONArray all)throws Exception{android.content.SharedPreferences.Editor edit=packs.prefs.edit().putString("voice-profiles-v1",LocalSecurity.seal(all.toString()));JSONObject self=null;for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("id").equals(SELF)&&all.getJSONObject(i).optBoolean("enabled",true))self=combined(all.getJSONObject(i),packs.pack("speaker").getString("version"));if(self==null)edit.remove("my-voice");else edit.putString("my-voice",LocalSecurity.seal(self.toString()));if(!edit.commit())throw new IOException("声纹保存失败");}
 static String create(OfflinePacks packs,String name)throws Exception{synchronized(LOCK){name=name.trim();if(name.isEmpty()||name.length()>60)throw new IOException("请输入 1–60 字的人物名称");JSONArray all=read(packs);if(all.length()>=30)throw new IOException("最多登记 30 位说话人");String id=UUID.randomUUID().toString();all.put(new JSONObject().put("id",id).put("name",name).put("enabled",true).put("samples",new JSONArray()));write(packs,all);return id;}}
 static void change(OfflinePacks packs,String id,String key,Object value)throws Exception{synchronized(LOCK){if(!key.equals("name")&&!key.equals("enabled"))throw new IOException("无效声纹操作");if(key.equals("name")&&(value.toString().trim().isEmpty()||value.toString().length()>60))throw new IOException("请输入 1–60 字名称");JSONArray all=read(packs);find(all,id).put(key,value);write(packs,all);}}
 static void remove(OfflinePacks packs,String id,String sample)throws Exception{synchronized(LOCK){JSONArray all=read(packs),kept=new JSONArray();for(int i=0;i<all.length();i++){JSONObject person=all.getJSONObject(i);if(person.optString("id").equals(id)){if(sample==null)continue;JSONArray samples=person.getJSONArray("samples"),remaining=new JSONArray();for(int n=0;n<samples.length();n++)if(!samples.getJSONObject(n).optString("id").equals(sample))remaining.put(samples.getJSONObject(n));person.put("samples",remaining);}kept.put(person);}write(packs,kept);}}
 static String add(OfflinePacks packs,String id,JSONObject profile,JSONObject source,JSONObject segment,boolean replace)throws Exception{synchronized(LOCK){JSONArray all=read(packs);JSONObject person;try{person=find(all,id);}catch(IOException missing){if(!id.equals(SELF))throw missing;person=new JSONObject().put("id",SELF).put("name","本人").put("enabled",true).put("samples",new JSONArray());all.put(person);}JSONArray samples=replace?new JSONArray():person.getJSONArray("samples");if(samples.length()>=20)throw new IOException("每人最多 20 个样本，请先移除不合适的样本");JSONObject sample=new JSONObject().put("id",UUID.randomUUID().toString()).put("created",System.currentTimeMillis()).put("origin",source==null?"enrollment":"recording").put("profile",profile);if(source!=null)sample.put("source_id",source.getString("id")).put("source_title",source.optString("title")).put("source_revision",source.optLong("transcript_revision")).put("start_ms",segment.optLong("start_ms")).put("end_ms",segment.optLong("end_ms"));samples.put(sample);person.put("samples",samples);write(packs,all);return sample.getString("id");}}
 static void assign(OfflinePacks packs,JSONArray segments,List<SpeakerMatcher.Observation> observations)throws Exception{JSONArray all=read(packs);ArrayList<JSONObject> people=new ArrayList<>();ArrayList<SpeakerMatcher.Profile> profiles=new ArrayList<>();String version=packs.pack("speaker").getString("version");for(int i=0;i<all.length();i++){JSONObject p=all.getJSONObject(i);if(!p.optBoolean("enabled",true))continue;JSONObject profile=combined(p,version);if(profile==null)continue;people.add(p);profiles.add(new SpeakerMatcher.Profile(profile));}for(SpeakerMatcher.Observation o:observations){JSONObject segment=segments.getJSONObject(o.segment);if(segment.optBoolean("speaker_confirmed"))continue;double best=-1,second=-1;int match=-1;for(int i=0;i<profiles.size();i++){double score=profiles.get(i).score(o.vector);if(score>best){second=best;best=score;match=i;}else second=Math.max(second,score);}if(match>=0&&best>=SpeakerMatcher.STRONG){if(best-second>=.08){JSONObject p=people.get(match);segment.put("speaker",p.getString("name")+"（候选）").put("voice_profile_id",p.getString("id")).put("voice_similarity",best).put("speaker_confidence","candidate");}else{segment.put("speaker","身份不确定").put("speaker_confidence","ambiguous-profiles");segment.remove("voice_profile_id");}}}}
}
